import pandas as pd, numpy as np
from scipy import stats
for i in [1,2,3,4,6,8]:
    try:
        df = pd.read_csv(eval(f"experiment_{i}_csv"))
        print(f"--- exp{i} cols:", list(df.columns))
        print(df.describe().round(2).to_string())
        if 'JobThroughput' in df and 'InterfaceErrorCounter' in df:
            r,p = stats.pearsonr(df['InterfaceErrorCounter'], df['JobThroughput'])
            print(f"  IErr vs Thru r={r:.3f} p={p:.1e}")
        if 'JobThroughput' in df and 'RackInletTemp' in df:
            r,p = stats.pearsonr(df['RackInletTemp'], df['JobThroughput'])
            print(f"  Temp vs Thru r={r:.3f} p={p:.1e}")
    except Exception as e:
        print(i, "err", e)

